rule "UniFi - parse CEF"
when
  has_field("unifi_log_format") && to_string($message.unifi_log_format) == "cef"
then
  let capture = regex(pattern: "(CEF:\\d+\\|Ubiquiti\\|UniFi Network\\|.*)$", value: to_string($message.message));
  let cef = parse_cef(to_string(capture["0"]), true);
  set_fields(cef);
  set_field("event_source_product", "unifi_network");
  set_field("vendor_name", "Ubiquiti");
  set_field("vendor_product", "UniFi Network");
  set_field("unifi_severity", "info");
  set_field("unifi_parse_status", "unsupported");
end

rule "UniFi - normalize device reboot"
when
  has_field("unifi_vendor_message") &&
  contains(
    value: to_string($message.unifi_vendor_message),
    search: "ace_reporter.reporter_handle_response_json(): [reboot] reboot"
  )
then
  set_field("event_action", "reboot");
  set_field("unifi_event_type", "device.reboot");
  set_field("unifi_parse_status", "parsed");
end

rule "UniFi - normalize switch port link"
when
  has_field("unifi_vendor_message") &&
  regex(
    pattern: "Port (?<port>\\d+) link (?<state>up|down)$",
    value: to_string($message.unifi_vendor_message)
  ).matches == true
then
  let link = regex(
    pattern: "Port (?<port>\\d+) link (?<state>up|down)$",
    value: to_string($message.unifi_vendor_message)
  );
  set_field("unifi_switch_port", to_long(link["port"]));
  set_field("event_action", lowercase(to_string(link["state"])));
  set_field("unifi_event_type", concat("network.port.", lowercase(to_string(link["state"]))));
  set_field("unifi_parse_status", "parsed");
end

